#!/usr/bin/env node
// Track Me Live schema contract → TypeScript, Swift and Kotlin.
//
// Source of truth: code/shared/schema/schema.json (JSON Schema 2020-12 for FSD §6, plus the createSession
// callable payloads).
//
//   node code/shared/schema/build.mjs           write generated/{ts,swift,kotlin}
//   node code/shared/schema/build.mjs --check   exit 1 if any generated file is stale
//
// Output:
//   generated/ts/schema.ts           types, enum value lists, path helpers, constants, the mascot catalog and a
//                                    dependency-free validator. Erasable syntax only (runs under Node type
//                                    stripping), no imports.
//   generated/swift/TMLSchema.swift  Codable + Sendable structs and enums (Foundation only).
//   generated/kotlin/TmlSchema.kt    Firestore-ready data classes (package live.trackme.schema).
//
// No dependencies; Node 18+.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(here, '../../..');
const schema = JSON.parse(fs.readFileSync(path.join(here, 'schema.json'), 'utf8'));
const OUT = {
  ts: path.join(here, 'generated/ts/schema.ts'),
  swift: path.join(here, 'generated/swift/TMLSchema.swift'),
  kotlin: path.join(here, 'generated/kotlin/TmlSchema.kt'),
};
const HEADER = 'Generated by code/shared/schema/build.mjs from code/shared/schema/schema.json. Do not edit by hand.';

const defs = schema.$defs;
const defNames = Object.keys(defs);
const camel = (s) => s.replace(/[-_]([a-z0-9])/g, (_, c) => c.toUpperCase());
const pascal = (s) => camel(s).replace(/^./, (c) => c.toUpperCase());
const upperSnake = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1_$2').replace(/[-\s]/g, '_').toUpperCase();
const doc = (s) => String(s ?? '').replace(/\*\//g, '*∕').replace(/\s+/g, ' ').trim();

// ---------- schema model ----------
const isEnumDef = (d) => Array.isArray(d.enum);
// 'string' | 'int' | 'mixed' (e.g. DefaultStop: 'call' | 15 | 30 | 60).
const enumKind = (d) => (d.enum.every((v) => typeof v === 'string') ? 'string' : d.enum.every((v) => Number.isInteger(v)) ? 'int' : 'mixed');
const swCase = (v) => (typeof v === 'number' ? `minutes${v}` : camel(v));
const kCase = (v) => (typeof v === 'number' ? `MINUTES_${v}` : upperSnake(v));
const allDefaulted = (defName) => Object.values(defs[defName].properties ?? {}).every((p) => p.default !== undefined);
const isTimeDef = (d) => d['x-tml-kind'] === 'timestamp';
const isMillisDef = (d) => d['x-tml-kind'] === 'epoch-millis';
const isMapDef = (d) => d.type === 'object' && !d.properties && d.additionalProperties === true;
const isStructDef = (d) => d.type === 'object' && !!d.properties && !isTimeDef(d);
const refName = (ref) => ref.replace('#/$defs/', '');

// Resolve a property schema to a field model.
function field(name, prop, required) {
  let p = prop;
  let nullable = false;
  if (p.anyOf) {
    const nonNull = p.anyOf.filter((x) => x.type !== 'null');
    if (nonNull.length !== 1 || p.anyOf.length !== 2) throw new Error(`${name}: unsupported anyOf`);
    nullable = true;
    p = { ...nonNull[0] };
  }
  if (Array.isArray(p.type)) {
    const t = p.type.filter((x) => x !== 'null');
    if (t.length !== 1) throw new Error(`${name}: unsupported type union`);
    nullable = p.type.includes('null');
    p = { ...p, type: t[0] };
  }
  const t = type(p, name);
  return { name, description: prop.description ?? '', required, nullable, optional: !required, default: prop.default, ...t };
}
function type(p, name) {
  if (p.$ref) {
    const r = refName(p.$ref);
    const d = defs[r];
    if (!d) throw new Error(`${name}: unknown $ref ${r}`);
    if (isTimeDef(d)) return { kind: 'timestamp' };
    if (isMillisDef(d)) return { kind: 'millis' };
    if (isEnumDef(d)) return { kind: 'enum', ref: r, enumKind: enumKind(d) };
    if (isMapDef(d)) return { kind: 'map', ref: r };
    if (isStructDef(d)) return { kind: 'struct', ref: r };
    if (d.type === 'string') return { kind: 'string', ref: r };
    throw new Error(`${name}: unsupported $ref target ${r}`);
  }
  switch (p.type) {
    case 'string': return { kind: 'string' };
    case 'boolean': return { kind: 'boolean' };
    case 'integer': return { kind: 'integer' };
    case 'number': return { kind: 'number' };
    case 'array': return { kind: 'array', items: type(p.items, `${name}[]`) };
    default: throw new Error(`${name}: unsupported type ${p.type}`);
  }
}
const fieldsOf = (defName) => {
  const d = defs[defName];
  const req = new Set(d.required ?? []);
  return Object.entries(d.properties).map(([n, p]) => field(n, p, req.has(n)));
};

const enumDefs = defNames.filter((n) => isEnumDef(defs[n]));
const structDefs = defNames.filter((n) => isStructDef(defs[n]));
const mapDefs = defNames.filter((n) => isMapDef(defs[n]));
const apiDefs = structDefs.filter((n) => defs[n]['x-api']);
const docDefs = structDefs.filter((n) => !defs[n]['x-api']);
const collections = schema['x-collections'];
const constants = schema['x-constants'];
const catalog = schema['x-catalog'];

// Which defs (transitively) contain a Firestore timestamp → get a time type parameter in TS.
const usesTime = (defName, seen = new Set()) => {
  if (seen.has(defName)) return false;
  seen.add(defName);
  const walk = (t) => t.kind === 'timestamp' || (t.kind === 'struct' && usesTime(t.ref, seen)) || (t.kind === 'array' && walk(t.items));
  return fieldsOf(defName).some(walk);
};

// Path templates: "shareSessions/{sessionId}/pings/{pingId}" → params and builders.
function pathInfo(template) {
  const segs = template.split('/');
  const params = segs.filter((s) => /^\{.+\}$/.test(s)).map((s) => s.slice(1, -1));
  const collSegs = segs.slice(0, -1);
  const collParams = collSegs.filter((s) => /^\{.+\}$/.test(s)).map((s) => s.slice(1, -1));
  return { segs, params, collSegs, collParams };
}

// Mascot catalog sanity: the ids, sets and accessories must be enum members.
for (const m of catalog.mascots) {
  if (!defs.MascotId.enum.includes(m.id)) throw new Error(`catalog: unknown mascot ${m.id}`);
  if (!defs.MascotSet.enum.includes(m.set)) throw new Error(`catalog: unknown set ${m.set}`);
  for (const a of m.accessories) if (!defs.MascotAccessory.enum.includes(a)) throw new Error(`catalog: unknown accessory ${a}`);
}
if (catalog.mascots.length !== defs.MascotId.enum.length) throw new Error('catalog: every MascotId needs an entry');

// ======================================================================================
// TypeScript
// ======================================================================================
function buildTs() {
  const L = [];
  const jsdoc = (indent, text) => { if (doc(text)) L.push(`${indent}/** ${doc(text)} */`); };
  L.push(`// ${HEADER}`);
  L.push('// Plain TypeScript with erasable syntax only (no enums, namespaces or imports), so it runs under');
  L.push('// Node 22+ type stripping and bundles in Vite as is.');
  L.push('');
  L.push('/** A Firestore Timestamp. Both firebase-admin and the web SDK Timestamp satisfy this shape. */');
  L.push('export interface FirestoreTimestamp {');
  L.push('  readonly seconds: number;');
  L.push('  readonly nanoseconds: number;');
  L.push('  toMillis(): number;');
  L.push('  toDate(): Date;');
  L.push('}');
  L.push('');
  L.push(`/** ${doc(defs.EpochMillis.description)} */`);
  L.push('export type EpochMillis = number;');
  L.push('');
  L.push('// ---------- Enums ----------');
  L.push('');
  for (const n of enumDefs) {
    const d = defs[n];
    const values = d.enum.map((v) => JSON.stringify(v)).join(', ');
    jsdoc('', d.description);
    L.push(`export const ${upperSnake(n)}_VALUES = [${values}] as const;`);
    jsdoc('', d.description);
    L.push(`export type ${n} = (typeof ${upperSnake(n)}_VALUES)[number];`);
    L.push(`export const is${n} = (value: unknown): value is ${n} => (${upperSnake(n)}_VALUES as readonly unknown[]).includes(value);`);
    L.push('');
  }
  L.push('// ---------- Documents and payloads ----------');
  L.push('');
  for (const n of mapDefs) {
    jsdoc('', defs[n].description);
    L.push(`export type ${n} = Record<string, unknown>;`);
    L.push('');
  }
  const tsType = (f, timeParam) => {
    const base = (t) => {
      switch (t.kind) {
        case 'timestamp': return timeParam;
        case 'millis': return 'EpochMillis';
        case 'enum': case 'map': return t.ref;
        case 'struct': return usesTime(t.ref) ? `${t.ref}<${timeParam}>` : t.ref;
        case 'string': return 'string';
        case 'boolean': return 'boolean';
        case 'integer': case 'number': return 'number';
        case 'array': return `${base(t.items)}[]`;
        default: throw new Error(t.kind);
      }
    };
    return base(f) + (f.nullable ? ' | null' : '');
  };
  for (const n of [...structDefs]) {
    const d = defs[n];
    const time = usesTime(n);
    const lines = [doc(d.description)];
    if (d['x-collection']) lines.push(`Firestore: ${d['x-collection']}.`);
    if (d['x-version']) lines.push(`${d['x-version']} only.`);
    if (time) lines.push('TTime is the timestamp type: the SDK Timestamp when reading, and e.g. Timestamp | FieldValue when writing.');
    L.push(`/** ${lines.join(' ')} */`);
    L.push(`export interface ${n}${time ? '<TTime = FirestoreTimestamp>' : ''} {`);
    for (const f of fieldsOf(n)) {
      jsdoc('  ', f.description);
      L.push(`  ${f.name}${f.optional ? '?' : ''}: ${tsType(f, 'TTime')};`);
    }
    L.push('}');
    L.push('');
  }
  for (const n of structDefs.filter(allDefaulted)) {
    L.push(`/** ${n} for a new account (schema defaults). */`);
    L.push(`export const DEFAULT_${upperSnake(n)}: ${n} = {`);
    for (const f of fieldsOf(n)) L.push(`  ${f.name}: ${JSON.stringify(f.default)},`);
    L.push('};');
    L.push('');
  }
  L.push('/** The viewer\'s shared-back location: same shape as Ping, in shareSessions/{sessionId}/viewerPings. */');
  L.push('export type ViewerPing<TTime = FirestoreTimestamp> = Ping<TTime>;');
  L.push('');
  L.push('// ---------- Callable functions ----------');
  L.push('');
  const apis = [...new Set(apiDefs.map((n) => defs[n]['x-api']))];
  L.push('/** Callable function names. */');
  L.push(`export const CALLABLES = { ${apis.map((a) => `${a}: ${JSON.stringify(a)}`).join(', ')} } as const;`);
  L.push('/** Request and response payloads per callable. */');
  L.push('export interface CallableContracts {');
  for (const a of apis) {
    const req = apiDefs.find((n) => defs[n]['x-api'] === a && defs[n]['x-api-role'] === 'request');
    const res = apiDefs.find((n) => defs[n]['x-api'] === a && defs[n]['x-api-role'] === 'response');
    L.push(`  ${a}: { request: ${req}; response: ${res} };`);
  }
  L.push('}');
  L.push('');
  L.push('// ---------- Firestore paths ----------');
  L.push('');
  L.push('/** Path templates per collection (FSD §6). */');
  L.push('export const COLLECTION_TEMPLATES = {');
  for (const c of collections) L.push(`  ${c.name}: ${JSON.stringify(c.path)},`);
  L.push('} as const;');
  L.push('');
  const tsPath = (segs) => '`' + segs.map((s) => (/^\{.+\}$/.test(s) ? '${' + s.slice(1, -1) + '}' : s)).join('/') + '`';
  L.push('/** Document paths. */');
  L.push('export const docPaths = {');
  for (const c of collections) {
    const p = pathInfo(c.path);
    L.push(`  ${c.name}: (${p.params.map((x) => `${x}: string`).join(', ')}): string => ${tsPath(p.segs)},`);
  }
  L.push('} as const;');
  L.push('');
  L.push('/** Collection paths (the parent collection of each document type). */');
  L.push('export const collectionPaths = {');
  for (const c of collections) {
    const p = pathInfo(c.path);
    L.push(`  ${c.name}: (${p.collParams.map((x) => `${x}: string`).join(', ')}): string => ${tsPath(p.collSegs)},`);
  }
  L.push('} as const;');
  L.push('');
  L.push('// ---------- Constants (FSD values) ----------');
  L.push('');
  for (const k of constants) {
    L.push(`/** ${doc(k.description)} (FSD ${doc(k.fsd)}) */`);
    L.push(`export const ${upperSnake(k.name)} = ${JSON.stringify(k.value)};`);
  }
  L.push('');
  L.push('// ---------- Mascot catalog ----------');
  L.push('');
  L.push('export interface MascotCatalogEntry {');
  L.push('  readonly id: MascotId;');
  L.push('  readonly set: MascotSet;');
  L.push('  readonly accessories: readonly MascotAccessory[];');
  L.push('}');
  L.push(`/** ${doc(catalog.description)} */`);
  L.push('export const MASCOT_CATALOG: readonly MascotCatalogEntry[] = [');
  for (const m of catalog.mascots) L.push(`  { id: ${JSON.stringify(m.id)}, set: ${JSON.stringify(m.set)}, accessories: [${m.accessories.map((a) => JSON.stringify(a)).join(', ')}] },`);
  L.push('];');
  L.push(`export const DEFAULT_MASCOT_ID: MascotId = ${JSON.stringify(catalog.defaultMascot)};`);
  L.push(`export const DEFAULT_MASCOT_COLOR: MascotColor = ${JSON.stringify(catalog.defaultColor)};`);
  L.push('/** The accessories a mascot takes. */');
  L.push('export const mascotAccessories = (id: MascotId): readonly MascotAccessory[] => MASCOT_CATALOG.find((m) => m.id === id)?.accessories ?? [];');
  L.push('/** True when the accessory (or none) fits the mascot. */');
  L.push('export const mascotTakes = (id: MascotId, accessory: MascotAccessory | null): boolean => accessory === null || mascotAccessories(id).includes(accessory);');
  L.push('');
  L.push('// ---------- Validation ----------');
  L.push('');
  // Embed the $defs without descriptions or x- annotations (except x-tml-kind).
  const strip = (v) => {
    if (Array.isArray(v)) return v.map(strip);
    if (v && typeof v === 'object') {
      const o = {};
      for (const [k, x] of Object.entries(v)) {
        if (k === 'description' || (k.startsWith('x-') && k !== 'x-tml-kind' && k !== 'x-tml-length')) continue;
        o[k] = strip(x);
      }
      return o;
    }
    return v;
  };
  L.push('/** The schema\'s $defs, without descriptions, for validate(). */');
  L.push(`export const SCHEMA_DEFS = ${JSON.stringify(strip(defs), null, 2).replace(/\n/g, '\n')} as const;`);
  L.push('');
  L.push('export type SchemaDefName = keyof typeof SCHEMA_DEFS;');
  L.push('export interface ValidationIssue { readonly path: string; readonly message: string }');
  L.push('');
  L.push(VALIDATOR_TS);
  return L.join('\n') + '\n';
}

const VALIDATOR_TS = `type Node = { readonly [key: string]: unknown };
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const typeOk = (t: string, v: unknown): boolean => {
  switch (t) {
    case 'null': return v === null;
    case 'string': return typeof v === 'string';
    case 'boolean': return typeof v === 'boolean';
    case 'integer': return typeof v === 'number' && Number.isInteger(v);
    case 'number': return typeof v === 'number' && Number.isFinite(v);
    case 'array': return Array.isArray(v);
    case 'object': return isObj(v);
    default: return false;
  }
};

function check(node: Node, value: unknown, at: string, out: ValidationIssue[]): void {
  if (typeof node.$ref === 'string') {
    const name = node.$ref.replace('#/$defs/', '') as SchemaDefName;
    check(SCHEMA_DEFS[name] as unknown as Node, value, at, out);
    return;
  }
  if (Array.isArray(node.anyOf)) {
    const branches = node.anyOf as Node[];
    if (!branches.some((b) => { const tmp: ValidationIssue[] = []; check(b, value, at, tmp); return tmp.length === 0; })) {
      // Report the first non-null branch's issues: the most useful message.
      const main = branches.find((b) => b.type !== 'null') ?? branches[0];
      if (main) check(main, value, at, out);
    }
    return;
  }
  if (node['x-tml-kind'] === 'timestamp') {
    const ok = isObj(value) && typeof value.seconds === 'number' && typeof value.nanoseconds === 'number';
    if (!ok) out.push({ path: at, message: 'expected a Firestore Timestamp' });
    return;
  }
  if (node.type !== undefined) {
    const types = Array.isArray(node.type) ? (node.type as string[]) : [node.type as string];
    if (!types.some((t) => typeOk(t, value))) { out.push({ path: at, message: \`expected \${types.join(' or ')}\` }); return; }
    if (value === null) return;
  }
  if (Array.isArray(node.enum) && !(node.enum as unknown[]).includes(value)) {
    out.push({ path: at, message: \`expected one of \${(node.enum as unknown[]).map((x) => JSON.stringify(x)).join(', ')}\` });
    return;
  }
  if (typeof value === 'string') {
    // PersonName counts grapheme clusters (x-tml-length), like Swift String.count; otherwise code points.
    const len = node['x-tml-length'] === 'graphemes' && typeof Intl !== 'undefined' && 'Segmenter' in Intl
      ? [...new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(value)].length
      : [...value].length;
    if (typeof node.minLength === 'number' && len < node.minLength) out.push({ path: at, message: \`shorter than \${node.minLength}\` });
    if (typeof node.maxLength === 'number' && len > node.maxLength) out.push({ path: at, message: \`longer than \${node.maxLength}\` });
    if (typeof node.pattern === 'string' && !new RegExp(node.pattern, 'u').test(value)) out.push({ path: at, message: 'does not match the pattern' });
  }
  if (typeof value === 'number') {
    if (typeof node.minimum === 'number' && value < node.minimum) out.push({ path: at, message: \`below \${node.minimum}\` });
    if (typeof node.maximum === 'number' && value > node.maximum) out.push({ path: at, message: \`above \${node.maximum}\` });
    if (typeof node.exclusiveMinimum === 'number' && value <= node.exclusiveMinimum) out.push({ path: at, message: \`must be above \${node.exclusiveMinimum}\` });
    if (typeof node.exclusiveMaximum === 'number' && value >= node.exclusiveMaximum) out.push({ path: at, message: \`must be below \${node.exclusiveMaximum}\` });
  }
  if (Array.isArray(value)) {
    if (isObj(node.items)) value.forEach((v, i) => check(node.items as Node, v, \`\${at}[\${i}]\`, out));
    if (node.uniqueItems === true && new Set(value.map((v) => JSON.stringify(v))).size !== value.length) out.push({ path: at, message: 'items must be unique' });
  }
  if (isObj(value) && isObj(node.properties)) {
    const props = node.properties as Record<string, Node>;
    for (const key of (node.required as readonly string[] | undefined) ?? []) {
      if (!(key in value)) out.push({ path: \`\${at}.\${key}\`, message: 'is required' });
    }
    for (const [key, v] of Object.entries(value)) {
      const prop = props[key];
      if (prop) check(prop, v, \`\${at}.\${key}\`, out);
      else if (node.additionalProperties === false) out.push({ path: \`\${at}.\${key}\`, message: 'is not allowed' });
    }
  }
}

/** Checks a value against one schema definition. An empty array means valid. */
export function validate(def: SchemaDefName, value: unknown): ValidationIssue[] {
  const out: ValidationIssue[] = [];
  check(SCHEMA_DEFS[def] as unknown as Node, value, '$', out);
  return out;
}

/** Like validate(), but throws a TypeError listing the issues. */
export function assertValid<T>(def: SchemaDefName, value: unknown): T {
  const issues = validate(def, value);
  if (issues.length) throw new TypeError(\`\${def}: \${issues.map((i) => \`\${i.path} \${i.message}\`).join('; ')}\`);
  return value as T;
}`;

// ======================================================================================
// Swift
// ======================================================================================
const SWIFT_KEYWORDS = new Set(['default', 'set', 'get', 'class', 'struct', 'enum', 'case', 'in', 'is', 'as', 'return', 'where', 'protocol', 'extension', 'func', 'var', 'let', 'import', 'operator', 'self', 'Self', 'init', 'deinit', 'subscript', 'static', 'public', 'private', 'internal', 'open', 'fileprivate', 'true', 'false', 'nil', 'repeat', 'while', 'for', 'if', 'else', 'switch', 'break', 'continue', 'fallthrough', 'guard', 'defer', 'do', 'catch', 'throw', 'throws', 'try', 'super', 'Type', 'Protocol', 'any', 'some']);
const swiftId = (s) => (SWIFT_KEYWORDS.has(s) ? `\`${s}\`` : s);
const S = (n) => `TML${n}`; // Swift type prefix

function buildSwift() {
  const L = [];
  const sdoc = (indent, text) => { if (doc(text)) L.push(`${indent}/// ${doc(text)}`); };
  L.push(`// ${HEADER}`);
  L.push('// Codable models for Firestore (FSD §6), the callables and the viewer\'s auth claims. Foundation only.');
  L.push('// Firestore Timestamps decode to Date (FirebaseFirestore\'s Codable support does this).');
  L.push('');
  L.push('import Foundation');
  L.push('');
  L.push('// MARK: - Enums');
  L.push('');
  for (const n of enumDefs) {
    const d = defs[n];
    sdoc('', d.description);
    const kind = enumKind(d);
    if (kind === 'int') {
      L.push(`public enum ${S(n)}: Int, Codable, CaseIterable, Sendable {`);
      for (const v of d.enum) L.push(`    case ${swCase(v)} = ${v}`);
    } else if (kind === 'mixed') {
      // Strings and integers on the wire: Codable by hand.
      L.push(`public enum ${S(n)}: Codable, Hashable, CaseIterable, Sendable {`);
      for (const v of d.enum) L.push(`    case ${swiftId(swCase(v))}`);
      L.push('');
      L.push('    public init(from decoder: Decoder) throws {');
      L.push('        let c = try decoder.singleValueContainer()');
      L.push('        if let s = try? c.decode(String.self) {');
      L.push('            switch s {');
      for (const v of d.enum.filter((x) => typeof x === 'string')) L.push(`            case ${JSON.stringify(v)}: self = .${swCase(v)}`);
      L.push(`            default: throw DecodingError.dataCorruptedError(in: c, debugDescription: "Unknown ${n} \\(s)")`);
      L.push('            }');
      L.push('            return');
      L.push('        }');
      L.push('        let n = try c.decode(Int.self)');
      L.push('        switch n {');
      for (const v of d.enum.filter((x) => typeof x === 'number')) L.push(`        case ${v}: self = .${swCase(v)}`);
      L.push(`        default: throw DecodingError.dataCorruptedError(in: c, debugDescription: "Unknown ${n} \\(n)")`);
      L.push('        }');
      L.push('    }');
      L.push('');
      L.push('    public func encode(to encoder: Encoder) throws {');
      L.push('        var c = encoder.singleValueContainer()');
      L.push('        switch self {');
      for (const v of d.enum) L.push(`        case .${swCase(v)}: try c.encode(${JSON.stringify(v)})`);
      L.push('        }');
      L.push('    }');
    } else {
      L.push(`public enum ${S(n)}: String, Codable, CaseIterable, Sendable {`);
      for (const v of d.enum) {
        const id = camel(v);
        L.push(id === v ? `    case ${swiftId(id)}` : `    case ${swiftId(id)} = ${JSON.stringify(v)}`);
      }
    }
    L.push('}');
    L.push('');
  }
  if (mapDefs.length) {
  L.push('// MARK: - JSON value (open maps)');
  L.push('');
  L.push('/// Any JSON / Firestore value, for maps the FSD leaves open.');
  L.push('public enum TMLJSONValue: Codable, Hashable, Sendable {');
  L.push('    case null');
  L.push('    case bool(Bool)');
  L.push('    case number(Double)');
  L.push('    case string(String)');
  L.push('    case array([TMLJSONValue])');
  L.push('    case object([String: TMLJSONValue])');
  L.push('');
  L.push('    public init(from decoder: Decoder) throws {');
  L.push('        let c = try decoder.singleValueContainer()');
  L.push('        if c.decodeNil() { self = .null }');
  L.push('        else if let v = try? c.decode(Bool.self) { self = .bool(v) }');
  L.push('        else if let v = try? c.decode(Double.self) { self = .number(v) }');
  L.push('        else if let v = try? c.decode(String.self) { self = .string(v) }');
  L.push('        else if let v = try? c.decode([TMLJSONValue].self) { self = .array(v) }');
  L.push('        else { self = .object(try c.decode([String: TMLJSONValue].self)) }');
  L.push('    }');
  L.push('');
  L.push('    public func encode(to encoder: Encoder) throws {');
  L.push('        var c = encoder.singleValueContainer()');
  L.push('        switch self {');
  L.push('        case .null: try c.encodeNil()');
  L.push('        case .bool(let v): try c.encode(v)');
  L.push('        case .number(let v): try c.encode(v)');
  L.push('        case .string(let v): try c.encode(v)');
  L.push('        case .array(let v): try c.encode(v)');
  L.push('        case .object(let v): try c.encode(v)');
  L.push('        }');
  L.push('    }');
  L.push('}');
  L.push('');
  }
  for (const n of mapDefs) {
    sdoc('', defs[n].description);
    L.push(`public typealias ${S(n)} = [String: TMLJSONValue]`);
    L.push('');
  }
  const swiftType = (f) => {
    const base = (t) => {
      switch (t.kind) {
        case 'timestamp': return 'Date';
        case 'millis': return 'Int64';
        case 'enum': case 'map': case 'struct': return S(t.ref);
        case 'string': return 'String';
        case 'boolean': return 'Bool';
        case 'integer': return 'Int';
        case 'number': return 'Double';
        case 'array': return `[${base(t.items)}]`;
        default: throw new Error(t.kind);
      }
    };
    return base(f) + (f.nullable || f.optional ? '?' : '');
  };
  L.push('// MARK: - Documents and payloads');
  L.push('');
  for (const n of structDefs) {
    const d = defs[n];
    const fs_ = fieldsOf(n);
    sdoc('', d.description);
    if (d['x-collection']) L.push(`/// Firestore: \`${d['x-collection']}\`.`);
    if (d['x-api']) L.push(`/// Callable: \`${d['x-api']}\` (${d['x-api-role']}).`);
    L.push(`public struct ${S(n)}: Codable, Hashable, Sendable {`);
    for (const f of fs_) {
      sdoc('    ', f.description);
      L.push(`    public var ${swiftId(camel(f.name))}: ${swiftType(f)}`);
    }
    L.push('');
    L.push('    public init(');
    fs_.forEach((f, i) => {
      const t = swiftType(f);
      const dflt = f.default !== undefined ? ` = ${f.kind === 'enum' ? `.${swCase(f.default)}` : JSON.stringify(f.default)}` : t.endsWith('?') ? ' = nil' : '';
      L.push(`        ${camel(f.name)}: ${t}${dflt}${i < fs_.length - 1 ? ',' : ''}`);
    });
    L.push('    ) {');
    for (const f of fs_) L.push(`        self.${camel(f.name)} = ${swiftId(camel(f.name))}`);
    L.push('    }');
    L.push('');
    if (allDefaulted(n)) {
      L.push('    /// The defaults for a new account.');
      L.push(`    public static let defaults = ${S(n)}()`);
      L.push('');
    }
    L.push('    /// The Firestore field names (`Field.callActive.rawValue == "call_active"`).');
    L.push('    public enum CodingKeys: String, CodingKey, CaseIterable, Sendable {');
    for (const f of fs_) {
      const id = camel(f.name);
      L.push(id === f.name ? `        case ${swiftId(id)}` : `        case ${swiftId(id)} = ${JSON.stringify(f.name)}`);
    }
    L.push('    }');
    L.push('    public typealias Field = CodingKeys');
    L.push('');
    L.push('    // Required fields are always written, as null when empty (schema.json: every field present).');
    L.push('    public func encode(to encoder: Encoder) throws {');
    L.push('        var c = encoder.container(keyedBy: CodingKeys.self)');
    for (const f of fs_) {
      const id = camel(f.name);
      L.push(`        try c.${f.required ? 'encode' : 'encodeIfPresent'}(${swiftId(id) === id ? id : `self.${id}`}, forKey: .${swiftId(id)})`);
    }
    L.push('    }');
    L.push('}');
    L.push('');
  }
  L.push('/// The viewer\'s shared-back location: same shape as a ping, in `shareSessions/{sessionId}/viewerPings`.');
  L.push(`public typealias TMLViewerPing = ${S('Ping')}`);
  L.push('');
  L.push('// MARK: - Callables');
  L.push('');
  L.push('/// Callable function names.');
  L.push('public enum TMLCallable {');
  for (const a of [...new Set(apiDefs.map((n) => defs[n]['x-api']))]) L.push(`    public static let ${camel(a)} = ${JSON.stringify(a)}`);
  L.push('}');
  L.push('');
  L.push('// MARK: - Firestore paths');
  L.push('');
  L.push('/// Document and collection paths (FSD §6).');
  L.push('public enum TMLPaths {');
  const swPath = (segs) => '"' + segs.map((s) => (/^\{.+\}$/.test(s) ? `\\(${s.slice(1, -1)})` : s)).join('/') + '"';
  for (const c of collections) {
    const p = pathInfo(c.path);
    L.push(`    /// \`${c.path}\``);
    L.push(`    public static func ${c.name}(${p.params.map((x) => `${x}: String`).join(', ')}) -> String { ${swPath(p.segs)} }`);
    L.push(`    /// The collection holding \`${c.path}\`.`);
    L.push(`    public static func ${c.name}Collection(${p.collParams.map((x) => `${x}: String`).join(', ')}) -> String { ${swPath(p.collSegs)} }`);
  }
  L.push('}');
  L.push('');
  L.push('// MARK: - Constants (FSD values)');
  L.push('');
  L.push('public enum TMLSchemaConstants {');
  for (const k of constants) {
    L.push(`    /// ${doc(k.description)} (FSD ${doc(k.fsd)})`);
    L.push(`    public static let ${camel(k.name)} = ${JSON.stringify(k.value)}`);
  }
  L.push('}');
  L.push('');
  L.push('// MARK: - Mascot catalog');
  L.push('');
  L.push('public struct TMLMascotCatalogEntry: Hashable, Sendable {');
  L.push('    public let id: TMLMascotId');
  L.push('    public let set: TMLMascotSet');
  L.push('    public let accessories: [TMLMascotAccessory]');
  L.push('}');
  L.push('');
  L.push(`/// ${doc(catalog.description)}`);
  L.push('public enum TMLMascotCatalog {');
  L.push('    public static let all: [TMLMascotCatalogEntry] = [');
  for (const m of catalog.mascots) L.push(`        TMLMascotCatalogEntry(id: .${swiftId(camel(m.id))}, set: .${swiftId(camel(m.set))}, accessories: [${m.accessories.map((a) => `.${camel(a)}`).join(', ')}]),`);
  L.push('    ]');
  L.push(`    public static let defaultMascot: TMLMascotId = .${camel(catalog.defaultMascot)}`);
  L.push(`    public static let defaultColor: TMLMascotColor = .${camel(catalog.defaultColor)}`);
  L.push('');
  L.push('    /// The accessories a mascot takes.');
  L.push('    public static func accessories(for id: TMLMascotId) -> [TMLMascotAccessory] {');
  L.push('        all.first { $0.id == id }?.accessories ?? []');
  L.push('    }');
  L.push('');
  L.push('    /// True when the accessory (or none) fits the mascot.');
  L.push('    public static func takes(_ id: TMLMascotId, _ accessory: TMLMascotAccessory?) -> Bool {');
  L.push('        guard let accessory else { return true }');
  L.push('        return accessories(for: id).contains(accessory)');
  L.push('    }');
  L.push('}');
  L.push('');
  return L.join('\n');
}

// ======================================================================================
// Kotlin (Firestore Android SDK). Package live.trackme.schema.
// ======================================================================================
const KOTLIN_KEYWORDS = new Set(['as', 'break', 'class', 'continue', 'do', 'else', 'false', 'for', 'fun', 'if', 'in', 'interface', 'is', 'null', 'object', 'package', 'return', 'super', 'this', 'throw', 'true', 'try', 'typealias', 'typeof', 'val', 'var', 'when', 'while']);
const kId = (s) => (KOTLIN_KEYWORDS.has(s) ? `\`${s}\`` : s);

function buildKotlin() {
  const L = [];
  const kdoc = (indent, text) => { if (doc(text)) L.push(`${indent}/** ${doc(text)} */`); };
  L.push(`// ${HEADER}`);
  L.push('// Firestore-ready models (FSD §6): `doc.toObject(ShareSession::class.java)` and `set(...)` work as is.');
  L.push('// Field names stay snake_case on the wire through @PropertyName; enums map by their wire value');
  L.push('// (@PropertyName on each constant). The defaults exist only for Firestore\'s no-argument constructor.');
  L.push('@file:Suppress("unused")');
  L.push('');
  L.push('package live.trackme.schema');
  L.push('');
  L.push('import com.google.firebase.Timestamp');
  if (docDefs.some((n) => fieldsOf(n).some((f) => f.kind === 'enum' && f.enumKind === 'mixed'))) L.push('import com.google.firebase.firestore.Exclude');
  L.push('import com.google.firebase.firestore.PropertyName');
  L.push('');
  L.push('// ---------- Enums ----------');
  L.push('');
  for (const n of enumDefs) {
    const d = defs[n];
    kdoc('', d.description);
    const kind = enumKind(d);
    if (kind === 'mixed') {
      // Strings and integers on the wire. Firestore reads integers back as Long.
      L.push(`enum class ${n}(val wire: Any) {`);
      d.enum.forEach((v, i) => L.push(`    ${kCase(v)}(${typeof v === 'number' ? `${v}L` : JSON.stringify(v)})${i < d.enum.length - 1 ? ',' : ';'}`));
      L.push('');
      L.push('    companion object {');
      L.push(`        fun fromWire(value: Any?): ${n}? = entries.firstOrNull { it.wire == value || (value is Number && value !is Double && value !is Float && it.wire == value.toLong()) }`);
      L.push('    }');
    } else if (kind === 'int') {
      L.push(`enum class ${n}(val minutes: Int) {`);
      d.enum.forEach((v, i) => L.push(`    ${kCase(v)}(${v})${i < d.enum.length - 1 ? ',' : ';'}`));
      L.push('');
      L.push('    companion object {');
      L.push(`        fun fromMinutes(value: Int?): ${n}? = entries.firstOrNull { it.minutes == value }`);
      L.push('    }');
    } else {
      L.push(`enum class ${n}(val wire: String) {`);
      d.enum.forEach((v, i) => L.push(`    @PropertyName(${JSON.stringify(v)}) ${upperSnake(v)}(${JSON.stringify(v)})${i < d.enum.length - 1 ? ',' : ';'}`));
      L.push('');
      L.push('    companion object {');
      L.push(`        fun fromWire(value: String?): ${n}? = entries.firstOrNull { it.wire == value }`);
      L.push('    }');
    }
    L.push('}');
    L.push('');
  }
  for (const n of mapDefs) {
    kdoc('', defs[n].description);
    L.push(`typealias ${n} = Map<String, Any?>`);
    L.push('');
  }
  const kType = (t) => {
    switch (t.kind) {
      case 'timestamp': return 'Timestamp';
      case 'millis': return 'Long';
      case 'enum': case 'map': case 'struct': return t.ref;
      case 'string': return 'String';
      case 'boolean': return 'Boolean';
      case 'integer': return 'Int';
      case 'number': return 'Double';
      case 'array': return `List<${kType(t.items)}>`;
      default: throw new Error(t.kind);
    }
  };
  const kDefault = (f) => {
    if (f.nullable || f.optional) return 'null';
    switch (f.kind) {
      case 'timestamp': return 'Timestamp(0, 0)';
      case 'millis': return '0L';
      case 'enum': return `${f.ref}.${kCase(f.default ?? defs[f.ref].enum[0])}${f.enumKind === 'mixed' ? '.wire' : ''}`;
      case 'map': return 'emptyMap()';
      case 'struct': return `${f.ref}()`;
      case 'string': return '""';
      case 'boolean': return String(f.default ?? false);
      case 'integer': return '0';
      case 'number': return '0.0';
      case 'array': return 'emptyList()';
      default: throw new Error(f.kind);
    }
  };
  L.push('// ---------- Firestore documents ----------');
  L.push('');
  for (const n of docDefs) {
    const d = defs[n];
    const fs_ = fieldsOf(n);
    kdoc('', `${doc(d.description)}${d['x-collection'] ? ` Firestore: ${d['x-collection']}.` : ''}`);
    L.push(`data class ${n}(`);
    for (const f of fs_) {
      kdoc('    ', f.description);
      L.push(`    @get:PropertyName(${JSON.stringify(f.name)}) @set:PropertyName(${JSON.stringify(f.name)})`);
      const q = f.nullable || f.optional ? '?' : '';
      if (f.kind === 'enum' && f.enumKind === 'mixed') L.push(`    var ${camel(f.name)}Wire: Any${q} = ${kDefault(f)},`);
      else L.push(`    var ${kId(camel(f.name))}: ${kType(f)}${q} = ${kDefault(f)},`);
    }
    L.push(') {');
    for (const f of fs_.filter((x) => x.kind === 'enum' && x.enumKind === 'mixed')) {
      const fallback = `${f.ref}.${kCase(f.default ?? defs[f.ref].enum[0])}`;
      L.push(`    /** ${f.name} as a [${f.ref}] (${camel(f.name)}Wire holds the raw Firestore value). */`);
      L.push(`    @get:Exclude val ${kId(camel(f.name))}: ${f.ref}${f.nullable ? '?' : ''} get() = ${f.ref}.fromWire(${camel(f.name)}Wire)${f.nullable ? '' : ` ?: ${fallback}`}`);
      L.push('');
    }
    L.push('    /** Firestore field names, for queries and partial updates. */');
    L.push('    object Fields {');
    for (const f of fs_) L.push(`        const val ${upperSnake(f.name)} = ${JSON.stringify(f.name)}`);
    L.push('    }');
    L.push('}');
    L.push('');
  }
  L.push('/** The viewer\'s shared-back location: same shape as a ping, in shareSessions/{sessionId}/viewerPings. */');
  L.push('typealias ViewerPing = Ping');
  L.push('');
  L.push('// ---------- Callable payloads ----------');
  L.push('');
  const toWire = (f, expr) => {
    const q = f.nullable || f.optional ? '?' : '';
    if (f.kind === 'enum') return f.enumKind === 'int' ? `${expr}${q}.minutes` : `${expr}${q}.wire`;
    if (['string', 'boolean', 'integer', 'number', 'millis'].includes(f.kind)) return expr;
    throw new Error(`toMap: unsupported ${f.kind}`);
  };
  const fromWire = (f, expr) => {
    const nul = f.nullable || f.optional;
    const req = (v) => (nul ? v : `requireNotNull(${v}) { ${JSON.stringify(`${f.name} is missing`)} }`);
    switch (f.kind) {
      case 'string': return req(`${expr} as String?`);
      case 'boolean': return req(`${expr} as Boolean?`);
      case 'integer': return req(`(${expr} as Number?)?.toInt()`);
      case 'number': return req(`(${expr} as Number?)?.toDouble()`);
      case 'millis': return req(`(${expr} as Number?)?.toLong()`);
      case 'enum': return f.enumKind === 'int' ? req(`${f.ref}.fromMinutes((${expr} as Number?)?.toInt())`) : req(`${f.ref}.fromWire(${expr} as String?)`);
      default: throw new Error(`fromMap: unsupported ${f.kind}`);
    }
  };
  for (const n of apiDefs) {
    const d = defs[n];
    const fs_ = fieldsOf(n);
    kdoc('', `${doc(d.description)} Callable: ${d['x-api']} (${d['x-api-role']}).`);
    L.push(`data class ${n}(`);
    for (const f of fs_) {
      kdoc('    ', f.description);
      L.push(`    val ${kId(camel(f.name))}: ${kType(f)}${f.nullable || f.optional ? '?' : ''}${f.optional ? ' = null' : ''},`);
    }
    L.push(') {');
    if (d['x-api-role'] === 'request') {
      L.push('    /** The callable payload, with snake_case keys. */');
      L.push('    fun toMap(): Map<String, Any?> = buildMap {');
      for (const f of fs_) {
        const line = `put(${JSON.stringify(f.name)}, ${toWire(f, kId(camel(f.name)))})`;
        L.push(f.optional ? `        if (${kId(camel(f.name))} != null) ${line}` : `        ${line}`);
      }
      L.push('    }');
    } else {
      L.push('    companion object {');
      L.push('        /** Reads the callable result (`HttpsCallableResult.getData()`). */');
      L.push(`        fun fromMap(map: Map<*, *>): ${n} = ${n}(`);
      for (const f of fs_) L.push(`            ${kId(camel(f.name))} = ${fromWire(f, `map[${JSON.stringify(f.name)}]`)},`);
      L.push('        )');
      L.push('    }');
    }
    L.push('}');
    L.push('');
  }
  L.push('/** Callable function names. */');
  L.push('object TmlCallables {');
  for (const a of [...new Set(apiDefs.map((n) => defs[n]['x-api']))]) L.push(`    const val ${upperSnake(a)} = ${JSON.stringify(a)}`);
  L.push('}');
  L.push('');
  L.push('// ---------- Firestore paths ----------');
  L.push('');
  L.push('/** Document and collection paths (FSD §6). */');
  L.push('object TmlPaths {');
  const kPath = (segs) => '"' + segs.map((s) => (/^\{.+\}$/.test(s) ? `$${s.slice(1, -1)}` : s)).join('/') + '"';
  for (const c of collections) {
    const p = pathInfo(c.path);
    L.push(`    /** ${c.path} */`);
    L.push(`    fun ${c.name}(${p.params.map((x) => `${x}: String`).join(', ')}): String = ${kPath(p.segs)}`);
    L.push(`    /** The collection holding ${c.path}. */`);
    L.push(`    fun ${c.name}Collection(${p.collParams.map((x) => `${x}: String`).join(', ')}): String = ${kPath(p.collSegs)}`);
  }
  L.push('}');
  L.push('');
  L.push('// ---------- Constants (FSD values) ----------');
  L.push('');
  L.push('object TmlSchemaConstants {');
  for (const k of constants) {
    L.push(`    /** ${doc(k.description)} (FSD ${doc(k.fsd)}) */`);
    L.push(`    const val ${upperSnake(k.name)} = ${JSON.stringify(k.value)}`);
  }
  L.push('}');
  L.push('');
  L.push('// ---------- Mascot catalog ----------');
  L.push('');
  L.push('data class MascotCatalogEntry(val id: MascotId, val set: MascotSet, val accessories: List<MascotAccessory>)');
  L.push('');
  L.push(`/** ${doc(catalog.description)} */`);
  L.push('object MascotCatalog {');
  L.push('    val all: List<MascotCatalogEntry> = listOf(');
  for (const m of catalog.mascots) L.push(`        MascotCatalogEntry(MascotId.${upperSnake(m.id)}, MascotSet.${upperSnake(m.set)}, listOf(${m.accessories.map((a) => `MascotAccessory.${upperSnake(a)}`).join(', ')})),`);
  L.push('    )');
  L.push(`    val DEFAULT_MASCOT: MascotId = MascotId.${upperSnake(catalog.defaultMascot)}`);
  L.push(`    val DEFAULT_COLOR: MascotColor = MascotColor.${upperSnake(catalog.defaultColor)}`);
  L.push('');
  L.push('    /** The accessories a mascot takes. */');
  L.push('    fun accessoriesFor(id: MascotId): List<MascotAccessory> = all.firstOrNull { it.id == id }?.accessories.orEmpty()');
  L.push('');
  L.push('    /** True when the accessory (or none) fits the mascot. */');
  L.push('    fun takes(id: MascotId, accessory: MascotAccessory?): Boolean = accessory == null || accessory in accessoriesFor(id)');
  L.push('}');
  L.push('');
  return L.join('\n');
}

// ---------- write or check ----------
const outputs = { [OUT.ts]: buildTs(), [OUT.swift]: buildSwift(), [OUT.kotlin]: buildKotlin() };
const check = process.argv.includes('--check');
const rel = (p) => path.relative(repo, p);
let stale = false;
for (const [file, content] of Object.entries(outputs)) {
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (check) {
    if (current !== content) { console.error(`stale: ${rel(file)}`); stale = true; }
  } else if (current !== content) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
    console.log(`wrote ${rel(file)} (${content.length} bytes)`);
  } else {
    console.log(`up to date ${rel(file)}`);
  }
}
if (stale) {
  console.error('Schema types are stale. Run `node code/shared/schema/build.mjs`.');
  process.exit(1);
}
if (check) console.log('schema: all generated files are up to date');
